DROP TABLE IF EXISTS `order_heads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_heads` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) unsigned NOT NULL,
  `head_pricing_rule_id` bigint(20) unsigned NOT NULL,
  `quantity` int(11) NOT NULL,
  `price_snapshot` decimal(10,2) NOT NULL,
  `subtotal` decimal(10,2) NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `order_heads_order_id_foreign` (`order_id`),
  KEY `order_heads_head_pricing_rule_id_foreign` (`head_pricing_rule_id`),
  CONSTRAINT `order_heads_head_pricing_rule_id_foreign` FOREIGN KEY (`head_pricing_rule_id`) REFERENCES `head_pricing_rules` (`id`),
  CONSTRAINT `order_heads_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6159 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
