--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `order_no` varchar(191) DEFAULT NULL,
  `subtotal` decimal(8,2) NOT NULL,
  `total_discount` decimal(8,2) NOT NULL DEFAULT 0.00,
  `total` decimal(8,2) NOT NULL,
  `discount_type` varchar(191) DEFAULT NULL,
  `status` varchar(191) NOT NULL DEFAULT 'paid',
  `cancelled` tinyint(1) NOT NULL DEFAULT 0,
  `cancelled_by` int(11) DEFAULT NULL,
  `cancellation_remarks` text DEFAULT NULL,
  `payment_method` varchar(191) DEFAULT NULL,
  `cash_amount` decimal(12,2) DEFAULT NULL,
  `change_amount` decimal(12,2) DEFAULT NULL,
  `table_number` varchar(191) DEFAULT NULL,
  `voucher_no_used` varchar(191) DEFAULT NULL,
  `voucher_discount_used` decimal(8,2) DEFAULT 0.00,
  `discount_approving_manager_id` int(11) DEFAULT NULL,
  `cancel_approving_manager_id` int(11) DEFAULT NULL,
  `shift_id` bigint(2) unsigned NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `reservation_id` bigint(20) unsigned DEFAULT NULL,
  `reservation_fee_used` decimal(10,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (`id`),
  KEY `orders_user_id_foreign` (`user_id`),
  CONSTRAINT `orders_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5303 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
