--
-- Table structure for table `table_sessions`
--

DROP TABLE IF EXISTS `table_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `table_sessions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `customer_name` varchar(191) DEFAULT NULL,
  `event_name` varchar(191) DEFAULT NULL,
  `event_notes` text DEFAULT NULL,
  `ref_no` varchar(191) DEFAULT NULL,
  `table_id` bigint(20) unsigned NOT NULL,
  `pricing_scheme_id` bigint(20) unsigned DEFAULT NULL,
  `session_type` varchar(191) NOT NULL DEFAULT 'walk_in',
  `pax` int(11) NOT NULL,
  `status` enum('open','paid','closed','cancelled') NOT NULL DEFAULT 'open',
  `remarks` varchar(191) DEFAULT NULL,
  `frontdoor_id` bigint(20) unsigned NOT NULL,
  `cashier_id` bigint(20) unsigned DEFAULT NULL,
  `order_id` bigint(20) unsigned DEFAULT NULL,
  `total_amount` decimal(10,2) DEFAULT NULL,
  `opened_at` datetime NOT NULL DEFAULT current_timestamp(),
  `closed_at` datetime DEFAULT NULL,
  `is_shared` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `table_sessions_table_id_foreign` (`table_id`),
  KEY `table_sessions_frontdoor_id_foreign` (`frontdoor_id`),
  KEY `table_sessions_cashier_id_foreign` (`cashier_id`),
  KEY `table_sessions_order_id_foreign` (`order_id`),
  KEY `table_sessions_pricing_scheme_id_foreign` (`pricing_scheme_id`),
  CONSTRAINT `table_sessions_cashier_id_foreign` FOREIGN KEY (`cashier_id`) REFERENCES `users` (`id`),
  CONSTRAINT `table_sessions_frontdoor_id_foreign` FOREIGN KEY (`frontdoor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `table_sessions_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`),
  CONSTRAINT `table_sessions_pricing_scheme_id_foreign` FOREIGN KEY (`pricing_scheme_id`) REFERENCES `pricing_schemes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `table_sessions_table_id_foreign` FOREIGN KEY (`table_id`) REFERENCES `tables` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5768 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

